export const meta = {
  name: 'agent-corpus-mining',
  description: 'Mine 8GB of Claude/Codex/Grok transcripts + the lobu repo for recurring failure modes, token waste, owed work, and prod-readiness gaps',
  phases: [
    { title: 'Mine', detail: 'parallel miners over transcript corpora and repo' },
    { title: 'Verify', detail: 'adversarially check each candidate against committed code' },
    { title: 'Synthesize', detail: 'rank and dedupe into one actionable report' },
  ],
}

const FINDING_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['findings'],
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['title', 'category', 'evidence', 'recurrence', 'proposed_fix', 'value'],
        properties: {
          title: { type: 'string', description: 'One-line claim' },
          category: { type: 'string', enum: ['failure-mode', 'token-waste', 'owed-work', 'prod-gap'] },
          evidence: { type: 'string', description: 'Concrete: file paths, session dates, quoted lines, PR numbers. NO vague claims.' },
          recurrence: { type: 'integer', description: 'How many DISTINCT sessions/incidents show this. 1 = one-off.' },
          proposed_fix: { type: 'string', description: 'Specific: a CI guard, an AGENTS.md invariant, a code change, a harness setting.' },
          value: { type: 'string', enum: ['high', 'medium', 'low'] },
        },
      },
    },
  },
}

const VERDICT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['holds_up', 'reason', 'corrected_claim'],
  properties: {
    holds_up: { type: 'boolean', description: 'False if the finding is stale, already fixed, or unsupported by evidence.' },
    reason: { type: 'string' },
    corrected_claim: { type: 'string', description: 'Restated accurately, or empty if it does not hold up.' },
  },
}

const CLAUDE = '/Users/burakemre/.claude2/projects'
const CODEX = '/Users/burakemre/.codex/sessions'
const GROK = '/Users/burakemre/.grok/sessions'
const REPO = '/Users/burakemre/Code/lobu'

const COMMON = `
You are mining a corpus of AI-coding-agent session transcripts for HIGH-VALUE, RECURRING lessons.

CRITICAL RULES:
- Transcripts are JSONL. Each line is a JSON object. Use grep/rg with targeted patterns and python3 for parsing. NEVER cat whole files — they are megabytes each and will blow your context.
- Prefer: rg -l <pattern> <dir> to find files, then rg -o with context on just those.
- Report ONLY things with concrete evidence you can cite (file path, date, quoted snippet, PR number).
- Prioritize patterns that appear in MULTIPLE DISTINCT sessions. A one-off mistake is noise; a pattern that bit three times is a missing guard.
- Do NOT report generic software-engineering advice ("write more tests"). Only report things specific to THIS user's actual observed workflow and THIS codebase.
- The repo is at ${REPO}. Its AGENTS.md already encodes many lessons — read it FIRST and do NOT report anything already covered there. Your value is finding what is NOT yet encoded.
`

phase('Mine')

const MINERS = [
  {
    label: 'claude-failure-modes',
    prompt: `${COMMON}
Corpus: ${CLAUDE} (1158 Claude Code transcripts, 754 for the lobu project).

Hunt RECURRING FAILURE MODES: bugs that shipped, gates that were escaped, false-green situations, review findings that recurred across PRs, and "I thought it worked but it did not" moments.

Grep for signals like: "false positive", "actually broken", "reverted", "regression", "did not work", "still failing", "root cause", "I was wrong", "that is not the bug", "silently", "race", "stale", "flaky".

For each: what was the ROOT CAUSE CLASS, how many distinct sessions show it, and what guard (CI check, test, invariant) would have caught it automatically.`,
  },
  {
    label: 'claude-token-waste',
    prompt: `${COMMON}
Corpus: ${CLAUDE}.

Hunt TOKEN AND WALL-TIME WASTE. Find where sessions burned context or time for no yield.

Look for: repeated screenshots, re-reading the same file many times in one session, foreground polling/sleep loops, make review run repeatedly as a find-fix loop, agents dispatched for trivial single-command work, long tool outputs dumped into context (cat of large files, full test logs, git log dumps), context compaction events, sessions that hit limits.

Quantify where you can (e.g. "N screenshot tool calls in one session", "file X read 7 times"). Propose concrete harness fixes: settings.json changes, hook automation, output-filtering habits, allowlist entries.`,
  },
  {
    label: 'claude-owed-work',
    prompt: `${COMMON}
Corpus: ${CLAUDE} plus the memory dir /Users/burakemre/.claude/projects/-Users-burakemre-Code-lobu/memory/.

Hunt UNFINISHED / OWED WORK: things scoped or promised but never shipped.

Grep for: "OWED", "TODO", "follow-up", "next PR", "deferred", "blocked", "unmerged", "unpushed", "not verified", "still need", "prod verify".

Cross-check each against reality: is the PR actually merged? Use gh and git log in ${REPO} to verify. Report ONLY genuinely-still-open items, with the evidence that they are still open. Rank by value.`,
  },
  {
    label: 'codex-lessons',
    prompt: `${COMMON}
Corpus: ${CODEX} (1.2GB of Codex CLI rollout transcripts, organized by YYYY/MM/DD).

These are from a DIFFERENT agent tool on likely the same projects. Hunt for failure modes and workflow lessons, with emphasis on what is DIFFERENT from Claude sessions — where did Codex fail in ways Claude does not, or catch things Claude missed?

Focus on the most recent 4 months. Grep the same failure signals as above. Also note any workflow or prompt patterns that visibly worked BETTER here, since those are portable.`,
  },
  {
    label: 'grok-lessons',
    prompt: `${COMMON}
Corpus: ${GROK} (1.8GB of Grok CLI sessions).

First determine the on-disk format (ls, then inspect one small file). Then hunt for failure modes, recurring bugs, and workflow lessons, same signals as above.

If the corpus turns out to be unusable (binary, no real conversations, all config), say so plainly and return an empty findings array rather than inventing content.`,
  },
  {
    label: 'repo-prod-gaps-state',
    prompt: `${COMMON}
Target: the REPO at ${REPO}, not transcripts.

Audit MULTI-REPLICA CORRECTNESS and STATE HANDLING, which AGENTS.md calls a hard invariant.

Find: in-memory Maps/singletons/module-level caches holding state another replica must read or mutate; setInterval/setTimeout-driven state that assumes one process; anything that would break when the server scales past one pod. Also check for advisory-lock usage that could starve, and unbounded in-memory growth (leaks).

Read the actual code. Cite file:line. Only report real violations, not stylistic concerns.`,
  },
  {
    label: 'repo-prod-gaps-failopen',
    prompt: `${COMMON}
Target: the REPO at ${REPO}, not transcripts.

Audit FAIL-OPEN SECURITY AND AUTHZ PATHS.

Find: catch blocks that swallow an authz/permission error and continue; default-allow branches; guards that only run on one code path when there are several entry points (REST vs MCP vs SDK vs worker); credential handling that could leak a real secret to a worker (AGENTS.md says workers NEVER get real credentials); text/string matching used as a security boundary (the user has a standing lesson that a text matcher is never the boundary).

Read actual code, cite file:line. Prefer a few well-verified findings over many speculative ones.`,
  },
  {
    label: 'repo-test-gaps',
    prompt: `${COMMON}
Target: the REPO at ${REPO}, not transcripts.

Audit TEST-SUITE TRUSTWORTHINESS — where a green suite could be lying.

Find: tests that mock the very thing under test; tests asserting on an assumed error shape rather than the shape production actually throws; suites where a mock leaks across files; skipped/quarantined tests; critical paths (billing, authz, credential minting, event append) with NO integration coverage; CI config that could produce a false green (stale dist, build-order bugs, tests not actually running in CI).

Cite file:line and, for CI, the workflow file. Verify claims by reading, not assuming.`,
  },
]

const mined = await parallel(
  MINERS.map((m) => () =>
    agent(m.prompt, { label: m.label, phase: 'Mine', schema: FINDING_SCHEMA })
  )
)

const all = mined.filter(Boolean).flatMap((r) => r.findings || [])
log(`Mined ${all.length} raw findings from ${mined.filter(Boolean).length}/${MINERS.length} miners`)

// Barrier justified: dedupe across ALL miners before spending verify agents on duplicates.
const seen = new Set()
const unique = []
for (const f of all) {
  const key = (f.title || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().slice(0, 60)
  if (key && !seen.has(key)) { seen.add(key); unique.push(f) }
}

// Verify only what is worth the tokens: recurring or high-value.
const worthVerifying = unique
  .filter((f) => f.value === 'high' || (f.recurrence || 0) >= 2)
  .sort((a, b) => (b.recurrence || 0) - (a.recurrence || 0))
  .slice(0, 24)

log(`${unique.length} unique; verifying top ${worthVerifying.length}`)

phase('Verify')

const verified = await parallel(
  worthVerifying.map((f, i) => () =>
    agent(
      `${COMMON}

ADVERSARIAL VERIFICATION. Another agent produced this finding. Your job is to REFUTE it if you can.

TITLE: ${f.title}
CATEGORY: ${f.category}
EVIDENCE CLAIMED: ${f.evidence}
CLAIMED RECURRENCE: ${f.recurrence}
PROPOSED FIX: ${f.proposed_fix}

Check, against COMMITTED code (origin/main in ${REPO}) and the real corpus — not the working tree, not recollection:
1. Is the evidence real? Do the cited files/lines/PRs actually exist and say what is claimed?
2. Is it ALREADY FIXED or already encoded in AGENTS.md / docs/GOTCHAS.md / the memory dir? If so it does not hold up.
3. Is the recurrence claim honest, or was it one incident described several times?
4. Is the proposed fix actually actionable and correct?

Default to holds_up=false when evidence is thin or you cannot confirm it. A refuted finding is a SUCCESS, not a failure.`,
      { label: `verify:${(f.title || 'x').slice(0, 34)}`, phase: 'Verify', effort: 'high', schema: VERDICT_SCHEMA }
    ).then((v) => ({ finding: f, verdict: v }))
  )
)

const survivors = verified.filter(Boolean).filter((v) => v.verdict && v.verdict.holds_up)
log(`${survivors.length}/${worthVerifying.length} findings survived adversarial verification`)

phase('Synthesize')

const synthesis = await agent(
  `You are writing the final report for the repo owner (a senior engineer, the sole maintainer of the lobu codebase).

They asked: "what high-value things can we do to be more bug-free, prod-ready, and token-efficient?"

Here are the VERIFIED findings that survived adversarial checking:

${JSON.stringify(survivors.map((s) => ({ ...s.finding, verified_as: s.verdict.corrected_claim })), null, 2)}

Also, these findings were REFUTED and must NOT appear in the report:
${JSON.stringify(verified.filter(Boolean).filter((v) => v.verdict && !v.verdict.holds_up).map((v) => ({ title: v.finding.title, why_refuted: v.verdict.reason })), null, 2)}

Write a tight, ranked report. Requirements:
- Lead with the single highest-leverage change, not a preamble.
- Group into: (1) Bug-free / prod-ready, (2) Token & wall-time efficiency, (3) Owed work worth finishing.
- Every item: the claim, the evidence in one clause, and the specific fix. Cite file:line or PR numbers where available.
- Rank by (recurrence x value) / effort. Say which 3 you would do FIRST and why.
- Be honest about confidence. If something rests on thin evidence, say so.
- Plain prose and short bullets. No corporate filler, no restating the question, no "in conclusion".
- Also propose which findings deserve to become PERSISTENT MEMORY entries (durable, cross-session lessons) versus which are one-off tasks. List the memory-worthy ones explicitly with a suggested slug and a one-line body.`,
  { label: 'synthesize', phase: 'Synthesize', effort: 'high' }
)

return { report: synthesis, verified_count: survivors.length, refuted_count: verified.filter(Boolean).length - survivors.length, raw_count: all.length }

