input.command:
prev=""
while true; do
  s=$(gh pr checks 2283 --required --json name,bucket 2>/dev/null) || { sleep 30; continue; }
  [ -z "$s" ] && { sleep 30; continue; }
  cur=$(echo "$s" | jq -r '.[] | select(.bucket!="pending") | "\(.name): \(.bucket)"' | sort)
  comm -13 <(echo "$prev") <(echo "$cur")
  prev="$cur"
  echo "$s" | jq -e 'length>0 and all(.[]; .bucket!="pending")' >/dev/null 2>&1 && { echo "ALL REQUIRED CHECKS SETTLED"; break; }
  sleep 30
done

while true; do
  s=$(gh pr checks 2282 --required 2>/dev/null | grep -E '^pi-review') || { sleep 30; continue; }
  case "$s" in
    *pending*) sleep 30 ;;
    *) echo "$s"; echo "PI-REVIEW SETTLED"; break ;;
  esac
done

cd /Users/burakemre/.claude/projects/-Users-burakemre-Code-lobu/memory
python3 -c "
import re,glob,os
names={}
for f in glob.glob('*.md'):
    if f=='MEMORY.md': continue
    t=open(f).read()
    m=re.search(r'^name:\s*(\S+)', t, re.M)
    if m: names[m.group(1)]=f
new=['feedback_absence_needs_origin_main_grep.md','feedback_guards_must_assert_coverage.md','reference_org_composite_pk_scoping.md','feedback_compact_pr_status_and_ci_logs.md','feedback_post_merge_prod_verify_wakeup.md','reference_squash_merge_breaks_ancestry_checks.md']
bad=[]
for f in new:
    for l in re.findall(r'\[\[([a-z0-9-]+)\]\]', open(f).read()):
        if l not in names: bad.append((f,l))
print('broken links:', len(bad))
for f,l in bad: print('  ',f,'->',l)
"

