import { afterAll, beforeEach, describe, expect, it } from 'vitest';
import { reconcileDeviceCapabilities } from '../../worker-api/device-reconcile';
import { cleanupTestDatabase, getTestDb } from '../setup/test-db';
import { createTestOrganization, createTestUser } from '../setup/test-fixtures';

const sql = getTestDb();

/** A bundled device connector that exists in every deployment. */
const CONNECTOR = 'chrome';
const CAPABILITY = 'browser.tabs';

async function seedWorker(
  userId: string,
  orgId: string,
  opts: { fresh: boolean }
): Promise<string> {
  const workerId = `dev-${Math.random().toString(36).slice(2, 10)}`;
  const lastSeen = opts.fresh ? new Date() : new Date(Date.now() - 6 * 60 * 60 * 1000);
  const [row] = (await sql`
    INSERT INTO device_workers (
      user_id, worker_id, platform, capabilities, label, organization_id, last_seen_at
    ) VALUES (
      ${userId}, ${workerId}, 'macos',
      ${sql.json([CAPABILITY])}, 'Test Device', ${orgId}, ${lastSeen}
    )
    RETURNING id
  `) as unknown as Array<{ id: string }>;
  return String(row.id);
}

async function seedConn(
  orgId: string,
  userId: string,
  deviceWorkerId: string | null
): Promise<number> {
  const slug = `conn-${Math.random().toString(36).slice(2, 8)}`;
  const [row] = (await sql`
    INSERT INTO connections (
      organization_id, connector_key, slug, display_name, status,
      auth_profile_id, created_by, visibility, device_worker_id, created_at, updated_at
    ) VALUES (
      ${orgId}, ${CONNECTOR}, ${slug}, 'Device Connector', 'active',
      NULL, ${userId}, 'private', ${deviceWorkerId}::uuid, NOW(), NOW()
    )
    RETURNING id
  `) as unknown as Array<{ id: number }>;
  return Number(row.id);
}

async function pinsOf(ids: number[]) {
  const rows = (await sql`
    SELECT id, device_worker_id FROM connections
    WHERE id = ANY(${ids}::int[]) ORDER BY id
  `) as unknown as Array<{ id: number; device_worker_id: string | null }>;
  return rows.map((r) => ({ id: Number(r.id), device: r.device_worker_id }));
}

describe('device pin unique conflict', () => {
  let orgId: string;
  let userId: string;

  beforeEach(async () => {
    const user = await createTestUser();
    userId = user.id;
    // Auto-wire always targets the user's PERSONAL org.
    const org = await createTestOrganization({ ownerId: userId, isPersonal: true });
    orgId = org.id;
  });

  afterAll(async () => {
    await cleanupTestDatabase();
  });

  it('wires without throwing when a second live row already holds the fresh device', async () => {
    // Exactly one FRESH device (so reconcilePin has a single target), plus a
    // stale one that the older connection is pinned to.
    const stale = await seedWorker(userId, orgId, { fresh: false });
    const fresh = await seedWorker(userId, orgId, { fresh: true });

    const older = await seedConn(orgId, userId, stale);
    const newer = await seedConn(orgId, userId, fresh);
    expect(older).toBeLessThan(newer);

    // The lookup picks `older` (lowest id) and wants to pin it to `fresh` —
    // which `newer` already holds. Before the fix this throws a unique
    // violation, is swallowed by the catch, and logs the prod error.
    await reconcileDeviceCapabilities(userId);

    const pins = await pinsOf([older, newer]);
    // `newer` must keep the fresh device; `older` must NOT have been stolen
    // into a duplicate, and the org must not end up with two rows on one device.
    const onFresh = pins.filter((p) => p.device === fresh);
    expect(onFresh).toHaveLength(1);
    expect(onFresh[0].id).toBe(newer);
  });

  it('still pins a lone connection to the sole fresh device', async () => {
    const fresh = await seedWorker(userId, orgId, { fresh: true });
    const only = await seedConn(orgId, userId, null);

    await reconcileDeviceCapabilities(userId);

    const [pin] = await pinsOf([only]);
    expect(pin.device).toBe(fresh);
  });
});

