async function pinsOf(ids: number[]) {
  // `sql.array` / bare `${ids}::int[]` trips "malformed array literal" under
  // fetch_types:false (see docs/GOTCHAS.md) — compare as text instead.
  const wanted = ids.map(String);
  const rows = (await sql`
    SELECT id, device_worker_id FROM connections ORDER BY id
  `) as unknown as Array<{ id: number; device_worker_id: string | null }>;
  return rows
    .filter((r) => wanted.includes(String(r.id)))
    .map((r) => ({ id: Number(r.id), device: r.device_worker_id }));
}

